class Solution {
public:
    int makePrefSumNonNegative(std::vector<int>& nums) {
        std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
        long long running = 0;
        int ops = 0;
        for (int x : nums) {
            running += x;
            if (x < 0) pq.push(x);
            if (running < 0) {
                running -= pq.top();
                pq.pop();
                ops++;
            }
        }
        return ops;
    }
};

class Solution {
    public int makePrefSumNonNegative(int[] nums) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        long running = 0;
        int ops = 0;
        for (int x : nums) {
            running += x;
            if (x < 0) pq.offer(x);
            if (running < 0) {
                running -= pq.poll();
                ops++;
            }
        }
        return ops;
    }
}

var makePrefSumNonNegative = function(nums) {
    const pq = [];
    const push = (val) => {
        pq.push(val);
        let idx = pq.length - 1;
        while (idx > 0) {
            let p = (idx - 1) >> 1;
            if (pq[p] > pq[idx]) {
                let temp = pq[p];
                pq[p] = pq[idx];
                pq[idx] = temp;
                idx = p;
            } else break;
        }
    };
    const pop = () => {
        const top = pq[0];
        const end = pq.pop();
        if (pq.length > 0) {
            pq[0] = end;
            let idx = 0;
            const len = pq.length;
            while ((idx << 1) + 1 < len) {
                let left = (idx << 1) + 1;
                let right = left + 1;
                let best = (right < len && pq[right] < pq[left]) ? right : left;
                if (pq[best] < pq[idx]) {
                    let temp = pq[best];
                    pq[best] = pq[idx];
                    pq[idx] = temp;
                    idx = best;
                } else break;
            }
        }
        return top;
    };
    let running = 0;
    let ops = 0;
    for (const x of nums) {
        running += x;
        if (x < 0) push(x);
        if (running < 0) {
            running -= pop();
            ops++;
        }
    }
    return ops;
};
